+    if (serverForcesEncryption) {
+        if (wellKnownDisablesEncryption) {
+            console.warn("Conflicting encryption policies: server requires encryption but .well-known disables it");
+        }
+        return { allowChange: false, forcedValue: true };
+    }
+    if (wellKnownDisablesEncryption) return { allowChange: false, forcedValue: false };
+    return { allowChange: true };
